Follow this complete example.
```swift
struct Percentage {
    let value: Int
    init?(_ value: Int) {
        guard value >= 0 && value <= 100 else {
            return nil
        }
        self.value = value
    }
}
if let accepted = Percentage(75) {
    print(accepted.value)
}
print(Percentage(101) == nil)
```
Output:
```text
75
true
```

